<script setup lang="ts">import {ref} from 'vue';import * as api from '../api/studies';import * as datasets from '../api/datasets';import * as runs from '../api/runs';import {useResource} from '../hooks/useResource';import {refreshResources} from '../stores/resources';import {user} from '../stores/session';import PageTitle from '../components/common/PageTitle.vue';import Notice from '../components/common/Notice.vue';const{data,error}=useResource(api.list,[]),{data:ds}=useResource(datasets.list,[]);const name=ref('秋展观展顺序复核'),dataset=ref('ds-gallery'),support=ref(.1),length=ref(3),collapse=ref(true),message=ref('');async function submit(){try{await api.create({name:name.value,dataset_id:dataset.value,min_support:support.value,max_length:length.value,collapse_repeats:collapse.value});refreshResources();message.value=''}catch(e:any){message.value=e.message}}async function execute(id:string){try{const r=await runs.create({study_id:id});sessionStorage.setItem('journey-selected-run',r.id);location.hash='results'}catch(e:any){message.value=e.message}}</script><template><PageTitle chapter="04" title="先固定口径，再寻找子序列" description="子序列允许中间跳过触点；折叠只移除相邻重复，保留隔站返回。最长模式4，唯一序列最多160。"/><Notice :error="error||message"/><form v-if="user?.role!=='viewer'" class="paper form-grid" @submit.prevent="submit"><label>方案名称<input aria-label="方案名称" v-model="name"/></label><label>路径数据<select v-model="dataset"><option v-for="d in ds" :key="d.id" :value="d.id">{{d.name}}</option></select></label><label>最小旅程支持度<input v-model.number="support" type="number" min=".001" max="1" step=".001"/></label><label>最长模式<input v-model.number="length" type="number" min="1" max="4"/></label><label class="checkbox"><input v-model="collapse" type="checkbox"/>折叠连续重复触点</label><button class="primary">保存挖掘方案</button></form><section class="paper"><h2>顺序复核方案</h2><article v-for="s in data" :key="s.id" class="record"><div><b>{{s.name}}</b><small>支持度 {{s.min_support}} · 最长 {{s.max_length}} · {{s.collapse_repeats?'折叠连续重复':'保留连续重复'}}</small></div><button v-if="user?.role!=='viewer'" @click="execute(s.id)">运行序列复核 →</button></article></section></template>
